// TestBuildTrailReviewCommentInputSendsFullPatchAnchor guards the contract the
// API enforces: a unified_diff is rejected unless it carries expected_file_path,
// expected_file_hash, expected_start_line, expected_end_line and expected_lines.
// Sending only change_type and patch is what made --patch fail with a 400.
func TestBuildTrailReviewCommentInputSendsFullPatchAnchor(t *testing.T) {
	t.Parallel()
	anchor := &trailReviewPatchAnchor{
		FilePath:  "src/auth/session.ts",
		FileHash:  "0cfbf08886fca9a91cb753ec8734c84fcbe52c9f",
		StartLine: 88,
		EndLine:   91,
		Lines:     "old line\n",
	}
	input, err := buildTrailReviewCommentInput(trailReviewCommentAddOptions{
		Body:  "Token refresh should allow clock skew.",
		Patch: trailReviewPatch("src/auth/session.ts", "old"),
	}, anchor)
	if err != nil {
		t.Fatalf("buildTrailReviewCommentInput: %v", err)
	}
	change := input.SuggestedChange
	if change == nil || change.ChangeType != "unified_diff" {
		t.Fatalf("SuggestedChange = %#v", change)
	}
	if change.ExpectedFilePath == nil || *change.ExpectedFilePath != "src/auth/session.ts" {
		t.Fatalf("ExpectedFilePath = %#v", change.ExpectedFilePath)
	}
	if change.ExpectedFileHash == nil || *change.ExpectedFileHash != anchor.FileHash {
		t.Fatalf("ExpectedFileHash = %#v", change.ExpectedFileHash)
	}
	if change.ExpectedStartLine == nil || *change.ExpectedStartLine != 88 {
		t.Fatalf("ExpectedStartLine = %#v", change.ExpectedStartLine)
	}
	if change.ExpectedEndLine == nil || *change.ExpectedEndLine != 91 {
		t.Fatalf("ExpectedEndLine = %#v", change.ExpectedEndLine)
	}
	if change.ExpectedLines == nil || *change.ExpectedLines != "old line\n" {
		t.Fatalf("ExpectedLines = %#v", change.ExpectedLines)
	}
}

